import{_ as p,c as e,o as t,af as r}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"卷六（雜卦）","description":"伊川易傳 - 卷六（雜卦）","frontmatter":{"title":"卷六（雜卦）","description":"伊川易傳 - 卷六（雜卦）"},"headers":[],"relativePath":"classics/yichuan/007.md","filePath":"classics/yichuan/007.md"}'),s={name:"classics/yichuan/007.md"};function i(c,a,n,l,o,_){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="卷六-雜卦" tabindex="-1">卷六（雜卦） <a class="header-anchor" href="#卷六-雜卦" aria-label="Permalink to “卷六（雜卦）”">​</a></h1><p>第一段</p><p>乾剛坤柔，比樂師憂(1)。臨觀之義，或與或求。屯見而不失其居，蒙雜而著(2)。震，起也；艮，止也。損益，盛衰之始也。大畜，時也；無妄，災也(3)。萃聚而升不來也，謙輕而豫怠也。噬嗑，食也；賁，無色也。兌見而巽伏也(4)。隨，無故也；蠱，則飭也。剝，爛也；復，反也。晉，晝也；明夷，誅也(5)。井通而困相遇也。鹹，速也；恆，久也。渙，離也；節，止也。解，緩也；蹇，難也。睽，外也；家人，內也。否泰，反其類也(6)。大壯則止，遯則退也。大有，眾也；同人，親也。革，去故也；鼎，取新也(7)。小過，過也；中孚，信也。豐，多故也；親寡，旅也。離上而坎下也⑧。小畜，寡也；履，不處也。需，不進也；訟，不親也。大過，顛也。姤，遇也，柔遇剛也。漸，女歸待男行也(9)。頤，養正也，即濟，定也。歸妹，女之終也。未濟，男之窮也。夬，決也。剛決柔也。君子道長，小人道憂也。(10)</p><h3 id="註釋" tabindex="-1">註釋 <a class="header-anchor" href="#註釋" aria-label="Permalink to “註釋”">​</a></h3><p>①乾剛：《乾》卦六爻由純陽組成，故曰乾剛。坤柔：《坤》卦六爻由純陰組成，故曰坤柔。比樂：《比》有親輔之義，故樂。師憂：《師》主軍旅，動從行險，故憂。</p><p>②或與或求：或者為施予或者為營求。與，施予；求：營求。《臨》二陽在四陰之下，有在上而臨下之義，故曰“與”。《觀》二陽在四陰之上，“大觀在上”有下以仰觀上之義，故曰“求”。屯見：《屯》為“物之始生”故曰“見”。見，現。不失其居：指各居其所。《屯》二陽皆當位，故曰“不失其居”。蒙雜：《蒙》二陽失位，陰陽雜居。“屯見而不失其居，蒙雜而著”當為《雜卦》作者以當時傳授的象義解《屯》《蒙》二卦。“屯見”、“蒙雜”以及“居”、“著”究竟確義為何，先儒雖有種種解說，恐皆未得實。筆者在此雖參照先儒之說解之，但仍覺不妥，故言明以待來者。</p><p>③盛衰之始：《損》＄為減損《泰》＄下而增益其上，即《彖》所謂“損下益上”，故為衰之始。泰為盛。《益》＄為減損《否》＄上增益其下，即《彖》所謂“損上益下”，故為盛之始。否為衰。時：待時。古“時”、“待”通。王引之雲：“家大人（王念孫）</p><p>第三段</p><p>曰：‘時：當讀為待，經言：歸妹愆期，遲歸有時。故《傳》申之曰：愆期之志，有待而行也’”大畜有畜養其德之義，故曰“時”。災：《無妄》為大旱卦。《集解》引京氏注《無妄》卦：“大旱之年，萬物皆死，無所復生。”故《彖》稱：“天命不祐。”故曰“災”。</p><p>④不平：即《序卦》所謂“聚而上者謂之升”。《萃》卦三陰聚於下，《升》卦三陰在於上，故曰“不來”。到內曰來，到外稱往。不來，指不在內而在外。謙輕：《謙》卦有謙退之義，故曰輕。豫怠：《豫》卦有娛樂之義，故怠。怠，和樂。一本作怡，怠、怡二字通。食：吃。噬嗑是指口中有物，故曰食。無色：即白色。《賁》離日在艮山下而無光，故曰“無色”。兌見而巽狀：兌陰在上故曰“見”，巽陰在下故曰“伏”。</p><p>⑤無故：無事。《隨《卦》有隨時而安之義，即《象傳》所謂“君子以嚮晦入宴息”。故為“無故”。飭：一本作“飾”，訓為整治，《蠱》為有事之卦，《序卦》“蠱者，事也”，有事則需要修整，故曰“飭”。爛：熟爛。《剝》一陽被五陰剝落，象果熟爛被剝落一樣，故曰“爛”。反：通“返”。《復》一陽復返於初，故曰“反”。晝：《晉》卦下坤為地，上離為日，日出地上，故為“晝”。誅：傷。《明夷》下離為日，上坤為地，日入地中，其光明受傷，故曰“誅”。</p><p>⑥井通而困相遇：井水本在下，而《井》卦水在木上，以承水而上，“井養而不窮”，“往來不窮”故謂之“通”。而《困》相反，水在澤下，澤上無水而乾涸，故曰“不通”，不通即是阻隔。速：神速。《鹹》卦有感之義。“二氣感應”，感而遂通，不行而至，故稱“速”。離：《渙》感之義。“二氣感應”，感而遂通，不行而至，故稱“速”。離：《渙》卦有披離解散之象，故曰“離”。止：《節》卦有節止之義，故曰“止”。緩：《解》卦有解除、緩解之義，故曰“緩”。難：《蹇》卦坎險在前，艮見險而止於內，有難之義。外：《序卦》：“睽者，乖也。”《廣雅·釋詁》：“乖，離也。”有離家之義。又《睽》離女在外卦，有女離家在外之義，故曰“外”。內：《家人》離女在內卦，女在家內故曰“內”。反其類：《泰》《否》卦畫相反，《否》反成《泰》，《泰》反成《否》，其事類相反。</p><p>⑦大壯則止：《大壯》四陽進消陰，陽長過半將止，故“止”。遯則退：《遯》陰進消陽，陽勢消退，故“遯則退”。眾：《大有》六五之柔得尊位，上下五陽皆應之，故曰眾。親：《同人》六二居中得位，眾陽皆親附，如《序卦》所稱：“與人同者，物必歸焉。”故曰“親”。革去故：《革》卦有改革、更新之義，故曰“去故”。故，指舊有。鼎取新：《鼎》卦離火在上，巽木生之，有鼎烹飪之象，鼎烹飪待熟而取新。</p><p>⑧過：《小過》陰盛過陽，故為“過”。過，經過。《序卦》：“有其信者必行之，故受之以小過。”信：《中孚》取信發於中，孚有信之義。故曰“信”。多故；《豐》乃日蝕之卦，古人多以日蝕為不祥，故曰“多故”。故，事。親寡：旅無所容身，故“親寡”。明何楷《古周易訂詁》引或曰：“‘親寡旅’當作‘旅寡親’，於韻亦協。”清崔述等從之，並作了詳細辯證，他說：“此傳之文，皆先舉卦名，而後釋其義，不容此句獨先釋之，而後倒之卦之後，一也。上文雲：‘豐多故’正與此文之‘旅寡親’兩兩相對。而‘親寡’亦不如‘寡親’之文義明順，二也。《大有》以下諸卦，皆真文韻，此句‘親’字正與上文‘親’、‘新’、‘信’三字相葉，三也。”（見《易卦圖說》）我們認為此考極確，故當改“親寡旅也”為“旅寡新也”。離上而坎下：離為火而炎上，坎為水而潤下。</p><p>⑨寡：《小畜》一陰畜五陽，陽眾陰寡，故曰“寡”。不處：不停止。履有踐履之義，且《履》卦陽爻皆以不處其位為吉，故曰“不處”。不進：《需》上坎為險，險在前，而待時，《需·彖》：“需，須也。”須為待，故“不進”。不親：《訟》卦上乾為天，下坎為水，天水相違行，故“不親”。顛：本義又指頭頂引申為顛覆。《大過》下巽為木，上兌為澤，木頂被澤水淹沒，故曰：“顛”。柔遇剛；《姤》卦一陰在下而上與五陽相遇，陰為柔，陽為剛。女歸待男行：指女子出嫁等待男子迎親。《漸》卦下艮為少男。上巽為長女，故有長女歸待少男行之義。</p><p>⑩養正：《頤》下震為動，上艮為止，上靜下動，人口吃物之象，故曰養正，如《彖》所言：“頤‘貞吉’，養正則吉也。”定：成。《既濟》六爻陰居陰位，陽居陽位，陰陽定位，故曰“定”。終：歸宿。《歸妹》上震為長男，為動，下兌為少女，為說，“說以動”，少女嫁長男之象，女子出嫁為“終”。男之窮：《未濟》三陽失正，陽窮極於上，故曰“男之窮”，陽為男。剛決柔：《夬》卦＄五陽盛長，決去一陰，君子道長，小人道憂：《夬》卦陽剛盛長，陰柔消退即將被決去，陽象“君子”，陰象“小人”，故曰“君子道長，小人道憂”。</p><p>《雜卦》雖不依六十四卦之順序，但兩兩為對解卦。前五十六卦皆然，獨後八卦錯亂。漢儒虞翻、晉儒乾寶皆認為此為《雜卦》作者獨心匠運、巧妙安排，故虞翻以互體釋之。以“喻武王伐紂”。乾寶以變通釋之，“以示來聖后王，明道非常道，事非常事也”。然漢鄭玄首先提出懷疑：“自此以下，卦意不協，以錯亂失正。”（見孫氏《周易》集解）</p><h3 id="第四段" tabindex="-1">第四段 <a class="header-anchor" href="#第四段" aria-label="Permalink to “第四段”">​</a></h3><p>但他“弗敢改耳。宋人蘇軾、朱震、蔡淵等人加以改定，元吳澄、明何楷等從之。改定後的次序有兩種：</p><p>頤，養正也；大過，顛也。姤，遇也，柔遇剛也；夬，決也，剛決柔也。君子道長，小人道憂也。漸，女歸待男行也；歸妹，女之終也。既濟，定也；未濟，男之窮也。此以蘇軾為代表。</p><p>大過，顛也；頤，養正也。既濟，定也；未濟，男之窮也。歸妹，女之終也；漸，女歸待男行也。姤，遇也，柔遇剛也；夬，決也，剛決柔也，君子道長，小人道憂也。以蔡淵為代表。案音韻學，當以後者勝。</p>',21)])])}const f=p(s,[["render",i]]);export{h as __pageData,f as default};
